def get_pilot_atoms(language_id: str) -> list[dict[str, Any]]:
    if language_id == "python":
        return list(PYTHON_PILOT_ATOMS)
    if language_id == "javascript":
        return list(JAVASCRIPT_PILOT_ATOMS)
    if language_id == "java":
        return list(JAVA_PILOT_ATOMS)
    return []


def get_atom(atom_id: str) -> dict[str, Any] | None:
    for atom in list(PYTHON_PILOT_ATOMS) + list(JAVASCRIPT_PILOT_ATOMS) + list(JAVA_PILOT_ATOMS):
        if atom["card_id"] == atom_id:
            return atom
    return None
